INSERT INTO `questions` VALUES (1,3,'What is C#?','C# is an object-oriented programming language developed by Microsoft for building various types of applications.','Junior','2026-07-03 16:10:15',NULL,NULL),(2,3,'What is the difference between a class and an object?','A class is a blueprint for creating objects, while an object is an instance of a class.','Junior','2026-07-03 16:10:15',NULL,NULL),(3,3,'What is encapsulation?','Encapsulation is the practice of hiding internal implementation details and exposing only necessary functionality.','Junior','2026-07-03 16:10:15',NULL,NULL),(4,3,'What is inheritance?','Inheritance allows a class to inherit properties and methods from another class.','Junior','2026-07-03 16:10:15',NULL,NULL),(5,3,'What is polymorphism?','Polymorphism allows objects of different types to be treated through a common interface or base class.','Junior','2026-07-03 16:10:15',NULL,NULL),(6,3,'What is the difference between value types and reference types?','Value types store data directly, while reference types store a reference to the data location in memory.','Mid','2026-07-03 16:10:15',NULL,NULL),(7,3,'What is the purpose of an interface?','An interface defines a contract that implementing classes must follow.','Mid','2026-07-03 16:10:15',NULL,NULL),(8,3,'What is LINQ?','LINQ is a query syntax in C# used to query and manipulate collections and data sources.','Mid','2026-07-03 16:10:15',NULL,NULL),(9,3,'What is dependency injection?','Dependency injection is a design pattern that provides dependencies from external sources rather than creating them internally.','Mid','2026-07-03 16:10:15',NULL,NULL),(10,3,'Explain async and await.','Async and await enable non-blocking asynchronous programming by allowing tasks to run without blocking the calling thread.','Mid','2026-07-03 16:10:15',NULL,NULL),(11,3,'How does garbage collection work in .NET?','The garbage collector automatically reclaims memory occupied by objects that are no longer referenced.','Senior','2026-07-03 16:10:15',NULL,NULL),(12,3,'What are delegates?','Delegates are type-safe references to methods and are commonly used for callbacks and events.','Senior','2026-07-03 16:10:15',NULL,NULL),(13,3,'What is the difference between IEnumerable and IQueryable?','IEnumerable executes queries in memory, while IQueryable enables query translation and execution by external providers such as databases.','Senior','2026-07-03 16:10:15',NULL,NULL),(14,3,'What are expression trees?','Expression trees represent code as data structures and are used by frameworks like Entity Framework to translate queries.','Senior','2026-07-03 16:10:15',NULL,NULL),(15,3,'Explain the SOLID principles.','SOLID is a set of five object-oriented design principles that improve maintainability, flexibility, and scalability of software.','Senior','2026-07-03 16:10:15',NULL,NULL),(16,1,'What is Android?','Android is a mobile operating system developed by Google and used to build applications for smartphones, tablets, and other devices.','Junior','2026-07-03 16:14:04',NULL,NULL),(17,1,'What is an Activity in Android?','An Activity represents a single screen with a user interface and serves as an entry point for user interactions.','Junior','2026-07-03 16:14:04',NULL,NULL),(18,1,'What is an Intent?','An Intent is a messaging object used to request actions from other Android components such as Activities, Services, or Broadcast Receivers.','Junior','2026-07-03 16:14:04',NULL,NULL),(19,1,'What is the AndroidManifest.xml file?','The AndroidManifest.xml file declares application components, permissions, and essential app configuration.','Junior','2026-07-03 16:14:04',NULL,NULL),(20,1,'What is the purpose of a Fragment?','A Fragment represents a reusable portion of the user interface that can be combined within Activities.','Junior','2026-07-03 16:14:04',NULL,NULL),(21,1,'Explain the Activity lifecycle.','The Activity lifecycle consists of callbacks such as onCreate, onStart, onResume, onPause, onStop, and onDestroy that manage an Activity state.','Mid','2026-07-03 16:14:04',NULL,NULL),(22,1,'What is ViewModel in Android?','A ViewModel stores and manages UI-related data in a lifecycle-conscious way, allowing data to survive configuration changes.','Mid','2026-07-03 16:14:04',NULL,NULL),(23,1,'What is LiveData?','LiveData is an observable data holder that automatically updates registered observers when data changes.','Mid','2026-07-03 16:14:04',NULL,NULL),(24,1,'What is the difference between Serializable and Parcelable?','Parcelable is Android-specific and more performant, while Serializable is a standard Java mechanism that is slower due to reflection.','Mid','2026-07-03 16:14:04',NULL,NULL),(25,1,'How do you store local data in Android?','Local data can be stored using SharedPreferences, Room Database, SQLite, files, or DataStore depending on the use case.','Mid','2026-07-03 16:14:04',NULL,NULL),(26,1,'What is dependency injection and how is it implemented in Android?','Dependency injection provides dependencies from external sources instead of creating them directly, commonly implemented using Hilt or Dagger.','Senior','2026-07-03 16:14:04',NULL,NULL),(27,1,'What is Room Database?','Room is an Android Jetpack library that provides an abstraction layer over SQLite and simplifies database operations.','Senior','2026-07-03 16:14:04',NULL,NULL),(28,1,'How would you prevent memory leaks in an Android application?','Memory leaks can be prevented by avoiding long-lived references to Activities, properly unregistering listeners, and using lifecycle-aware components.','Senior','2026-07-03 16:14:04',NULL,NULL),(29,1,'What is the difference between Coroutines and Threads?','Coroutines are lightweight asynchronous tasks managed by Kotlin, while threads are heavier operating system-managed execution units.','Senior','2026-07-03 16:14:04',NULL,NULL),(30,1,'Explain clean architecture in Android applications.','Clean architecture separates concerns into layers such as presentation, domain, and data to improve maintainability, testability, and scalability.','Senior','2026-07-03 16:14:04',NULL,NULL),(31,2,'What is Angular?','Angular is a TypeScript-based framework developed by Google for building single-page web applications.','Junior','2026-07-03 16:15:00',NULL,NULL),(32,2,'What is a Component in Angular?','A Component is the fundamental building block of an Angular application that controls a portion of the user interface.','Junior','2026-07-03 16:15:00',NULL,NULL),(33,2,'What is data binding in Angular?','Data binding synchronizes data between the component and the template.','Junior','2026-07-03 16:15:00',NULL,NULL),(34,2,'What is the purpose of directives in Angular?','Directives extend HTML functionality and allow manipulation of the DOM and component behavior.','Junior','2026-07-03 16:15:00',NULL,NULL),(35,2,'What is the difference between interpolation and property binding?','Interpolation displays component data in templates, while property binding sets DOM element properties.','Junior','2026-07-03 16:15:00',NULL,NULL),(36,2,'What is dependency injection in Angular?','Dependency injection is a design pattern that provides services and dependencies to components instead of creating them directly.','Mid','2026-07-03 16:15:00',NULL,NULL),(37,2,'What are Angular Services?','Services are classes used to encapsulate reusable business logic, data access, or shared functionality.','Mid','2026-07-03 16:15:00',NULL,NULL),(38,2,'What is the purpose of RxJS in Angular?','RxJS provides reactive programming capabilities using Observables to handle asynchronous data streams.','Mid','2026-07-03 16:15:00',NULL,NULL),(39,2,'What is an Observable?','An Observable is a stream of data that can emit multiple values over time and can be subscribed to by consumers.','Mid','2026-07-03 16:15:00',NULL,NULL),(40,2,'What are Angular lifecycle hooks?','Lifecycle hooks are methods such as ngOnInit and ngOnDestroy that allow developers to respond to component lifecycle events.','Mid','2026-07-03 16:15:00',NULL,NULL),(41,2,'What is lazy loading in Angular?','Lazy loading loads feature modules only when needed, reducing initial application load time and improving performance.','Senior','2026-07-03 16:15:00',NULL,NULL),(42,2,'How does change detection work in Angular?','Angular uses a change detection mechanism to update the view when application state changes.','Senior','2026-07-03 16:15:00',NULL,NULL),(43,2,'What is the difference between template-driven and reactive forms?','Template-driven forms are defined mainly in templates, while reactive forms are defined and managed programmatically in code.','Senior','2026-07-03 16:15:00',NULL,NULL),(44,2,'How would you optimize the performance of a large Angular application?','Performance can be improved using lazy loading, OnPush change detection, trackBy functions, caching, and minimizing unnecessary DOM updates.','Senior','2026-07-03 16:15:00',NULL,NULL),(45,2,'What is NgRx and when would you use it?','NgRx is a state management library based on Redux principles and is used to manage complex application state in a predictable manner.','Senior','2026-07-03 16:15:00',NULL,NULL),(46,4,'What is HTML?','HTML is the standard markup language used to structure and define content on web pages.','Junior','2026-07-03 16:15:58',NULL,NULL),(47,4,'What is the purpose of the <!DOCTYPE html> declaration?','It tells the browser that the document uses HTML5 and helps ensure standards-compliant rendering.','Junior','2026-07-03 16:15:58',NULL,NULL),(48,4,'What is the difference between block-level and inline elements?','Block-level elements take up the full width available and start on a new line, while inline elements only take up the space they need and do not start a new line.','Junior','2026-07-03 16:15:58',NULL,NULL),(49,4,'What is the purpose of the <a> tag?','The <a> tag is used to create hyperlinks that navigate to other pages, files, or locations.','Junior','2026-07-03 16:15:58',NULL,NULL),(50,4,'What are semantic HTML elements?','Semantic elements clearly describe their meaning and purpose, such as <header>, <article>, <section>, and <footer>.','Junior','2026-07-03 16:15:58',NULL,NULL),(51,4,'What is the difference between id and class attributes?','An id uniquely identifies a single element, while a class can be assigned to multiple elements.','Mid','2026-07-03 16:15:58',NULL,NULL),(52,4,'What is the purpose of the alt attribute on images?','The alt attribute provides alternative text for accessibility and when an image cannot be displayed.','Mid','2026-07-03 16:15:58',NULL,NULL),(53,4,'What is form validation in HTML?','Form validation ensures user input meets specified requirements before submission using attributes such as required, minlength, and pattern.','Mid','2026-07-03 16:15:58',NULL,NULL),(54,4,'What is the purpose of the meta tag?','Meta tags provide metadata about a document, such as character encoding, viewport settings, and SEO-related information.','Mid','2026-07-03 16:15:58',NULL,NULL),(55,4,'What is the difference between local storage and cookies?','Local storage stores larger amounts of data in the browser and is not sent to the server, while cookies are smaller and are included in HTTP requests.','Mid','2026-07-03 16:15:58',NULL,NULL),(56,4,'Why is semantic HTML important for accessibility?','Semantic HTML helps assistive technologies understand the structure and meaning of content, improving accessibility.','Senior','2026-07-03 16:15:58',NULL,NULL),(57,4,'What are ARIA attributes and when should they be used?','ARIA attributes improve accessibility by providing additional information to assistive technologies when native HTML semantics are insufficient.','Senior','2026-07-03 16:15:58',NULL,NULL),(58,4,'How does the browser construct the DOM from HTML?','The browser parses HTML and creates a Document Object Model tree representing the structure and content of the page.','Senior','2026-07-03 16:15:58',NULL,NULL),(59,4,'What is the purpose of the viewport meta tag in responsive design?','The viewport meta tag controls how the page is displayed and scaled on mobile devices.','Senior','2026-07-03 16:15:58',NULL,NULL),(60,4,'How would you optimize HTML for SEO and performance?','Use semantic markup, meaningful headings, descriptive metadata, optimized images, and minimize unnecessary elements to improve SEO and performance.','Senior','2026-07-03 16:15:58',NULL,NULL),(61,5,'What is CSS?','CSS is a style sheet language used to control the appearance and layout of HTML elements.','Junior','2026-07-03 16:16:34',NULL,NULL),(62,5,'What are the different ways to apply CSS to a webpage?','CSS can be applied using inline styles, internal style tags, or external stylesheet files.','Junior','2026-07-03 16:16:34',NULL,NULL),(63,5,'What is the difference between a class selector and an id selector?','A class selector can be applied to multiple elements, while an id selector should uniquely identify a single element.','Junior','2026-07-03 16:16:34',NULL,NULL),(64,5,'What is the CSS box model?','The box model consists of content, padding, border, and margin, which together define the space occupied by an element.','Junior','2026-07-03 16:16:34',NULL,NULL),(65,5,'What is the difference between relative and absolute units?','Relative units such as em and rem depend on other values, while absolute units such as px have fixed sizes.','Junior','2026-07-03 16:16:34',NULL,NULL),(66,5,'What is Flexbox and when would you use it?','Flexbox is a one-dimensional layout system used to align and distribute items within a container.','Mid','2026-07-03 16:16:34',NULL,NULL),(67,5,'What is CSS Grid?','CSS Grid is a two-dimensional layout system that allows developers to create complex row and column layouts.','Mid','2026-07-03 16:16:34',NULL,NULL),(68,5,'What is the difference between position: relative, absolute, fixed, and sticky?','Relative positions an element relative to its normal position, absolute positions relative to the nearest positioned ancestor, fixed positions relative to the viewport, and sticky toggles between relative and fixed based on scrolling.','Mid','2026-07-03 16:16:34',NULL,NULL),(69,5,'What is specificity in CSS?','Specificity determines which CSS rule is applied when multiple rules target the same element.','Mid','2026-07-03 16:16:34',NULL,NULL),(70,5,'How do media queries support responsive design?','Media queries apply different styles based on device characteristics such as screen width, height, or orientation.','Mid','2026-07-03 16:16:34',NULL,NULL),(71,5,'What is the difference between em and rem units?','Em units are relative to the font size of the parent element, while rem units are relative to the root html element font size.','Senior','2026-07-03 16:16:34',NULL,NULL),(72,5,'How would you optimize CSS performance on a large application?','Optimize CSS by reducing selector complexity, minimizing reflows and repaints, removing unused styles, and organizing styles efficiently.','Senior','2026-07-03 16:16:34',NULL,NULL),(73,5,'What causes layout shifts and how can they be prevented?','Layout shifts occur when content changes size or position unexpectedly and can be prevented by reserving space for dynamic elements and media.','Senior','2026-07-03 16:16:34',NULL,NULL),(74,5,'What are CSS custom properties (variables)?','CSS custom properties are reusable values defined with --name syntax that can be referenced throughout stylesheets using var().','Senior','2026-07-03 16:16:34',NULL,NULL),(75,5,'Explain the difference between reflow and repaint.','Reflow occurs when the browser recalculates layout due to structural changes, while repaint updates visual appearance without affecting layout.','Senior','2026-07-03 16:16:34',NULL,NULL),(76,6,'What is JavaScript?','JavaScript is a programming language used to create dynamic and interactive web applications.','Junior','2026-07-03 16:17:02',NULL,NULL),(77,6,'What is the difference between var, let, and const?','Var is function-scoped, while let and const are block-scoped. Const cannot be reassigned after initialization.','Junior','2026-07-03 16:17:02',NULL,NULL),(78,6,'What are JavaScript data types?','Common data types include string, number, boolean, null, undefined, object, bigint, and symbol.','Junior','2026-07-03 16:17:02',NULL,NULL),(79,6,'What is a function in JavaScript?','A function is a reusable block of code that performs a specific task and can accept parameters and return values.','Junior','2026-07-03 16:17:02',NULL,NULL),(80,6,'What is the difference between == and ===?','The == operator performs type coercion before comparison, while === compares both value and type without coercion.','Junior','2026-07-03 16:17:02',NULL,NULL),(81,6,'What is a closure in JavaScript?','A closure is a function that retains access to variables from its outer scope even after the outer function has finished executing.','Mid','2026-07-03 16:17:02',NULL,NULL),(82,6,'What is the purpose of the this keyword?','The this keyword refers to the object that is currently executing the function and its value depends on how the function is called.','Mid','2026-07-03 16:17:02',NULL,NULL),(83,6,'What are Promises?','Promises represent the eventual completion or failure of an asynchronous operation and its resulting value.','Mid','2026-07-03 16:17:02',NULL,NULL),(84,6,'What is async/await?','Async/await is syntactic sugar built on Promises that simplifies writing asynchronous code in a more readable manner.','Mid','2026-07-03 16:17:02',NULL,NULL),(85,6,'What is event bubbling?','Event bubbling is the process where an event triggered on a child element propagates upward through its parent elements.','Mid','2026-07-03 16:17:02',NULL,NULL),(86,6,'Explain the JavaScript event loop.','The event loop handles asynchronous operations by processing the call stack and task queues, enabling non-blocking execution.','Senior','2026-07-03 16:17:02',NULL,NULL),(87,6,'What is the difference between debounce and throttle?','Debounce delays execution until activity stops, while throttle limits execution to a specified interval.','Senior','2026-07-03 16:17:02',NULL,NULL),(88,6,'What is prototypal inheritance?','Prototypal inheritance allows objects to inherit properties and methods from other objects through the prototype chain.','Senior','2026-07-03 16:17:02',NULL,NULL),(89,6,'What are memory leaks in JavaScript and how can they be prevented?','Memory leaks occur when unused objects remain referenced. They can be prevented by removing unnecessary references, event listeners, and timers.','Senior','2026-07-03 16:17:02',NULL,NULL),(90,6,'How would you optimize the performance of a JavaScript application?','Performance can be improved through code splitting, lazy loading, caching, minimizing DOM manipulation, and optimizing expensive operations.','Senior','2026-07-03 16:17:02',NULL,NULL),(91,7,'What is Java?','Java is an object-oriented programming language designed to be platform-independent through the use of the Java Virtual Machine.','Junior','2026-07-03 16:17:32',NULL,NULL),(92,7,'What is the JVM?','The Java Virtual Machine executes Java bytecode and enables Java applications to run on different operating systems.','Junior','2026-07-03 16:17:32',NULL,NULL),(93,7,'What is the difference between JDK, JRE, and JVM?','The JVM executes Java programs, the JRE provides the runtime environment, and the JDK includes development tools in addition to the JRE.','Junior','2026-07-03 16:17:32',NULL,NULL),(94,7,'What is a class and an object in Java?','A class is a blueprint for creating objects, while an object is an instance of a class.','Junior','2026-07-03 16:17:32',NULL,NULL),(95,7,'What are the main principles of object-oriented programming?','The main principles are encapsulation, inheritance, polymorphism, and abstraction.','Junior','2026-07-03 16:17:32',NULL,NULL),(96,7,'What is the difference between an abstract class and an interface?','An abstract class can contain both implemented and abstract methods, while an interface defines a contract that classes must implement.','Mid','2026-07-03 16:17:32',NULL,NULL),(97,7,'What is method overloading and method overriding?','Overloading provides multiple methods with the same name but different parameters, while overriding provides a new implementation of a superclass method.','Mid','2026-07-03 16:17:32',NULL,NULL),(98,7,'What is the Java Collections Framework?','The Java Collections Framework is a set of classes and interfaces used to store and manipulate groups of objects.','Mid','2026-07-03 16:17:32',NULL,NULL),(99,7,'What is the difference between ArrayList and LinkedList?','ArrayList provides fast random access, while LinkedList is more efficient for frequent insertions and deletions.','Mid','2026-07-03 16:17:32',NULL,NULL),(100,7,'What is exception handling in Java?','Exception handling is a mechanism for managing runtime errors using try, catch, finally, throw, and throws.','Mid','2026-07-03 16:17:32',NULL,NULL),(101,7,'What is the difference between HashMap and ConcurrentHashMap?','HashMap is not thread-safe, while ConcurrentHashMap supports concurrent access with improved performance in multithreaded environments.','Senior','2026-07-03 16:17:32',NULL,NULL),(102,7,'How does garbage collection work in Java?','Garbage collection automatically reclaims memory occupied by objects that are no longer reachable by the application.','Senior','2026-07-03 16:17:32',NULL,NULL),(103,7,'What is the difference between checked and unchecked exceptions?','Checked exceptions must be handled or declared, while unchecked exceptions extend RuntimeException and do not require explicit handling.','Senior','2026-07-03 16:17:32',NULL,NULL),(104,7,'What is the Java Memory Model?','The Java Memory Model defines how threads interact through memory and guarantees visibility, ordering, and atomicity rules.','Senior','2026-07-03 16:17:32',NULL,NULL),(105,7,'How would you optimize the performance of a Java application?','Performance can be improved through efficient algorithms, proper collection selection, caching, minimizing object creation, profiling, and tuning JVM settings.','Senior','2026-07-03 16:17:32',NULL,NULL),(106,8,'What is Python?','Python is a high-level, interpreted programming language known for its readability and versatility.','Junior','2026-07-03 16:17:55',NULL,NULL),(107,8,'What are Python lists?','Lists are ordered, mutable collections that can store multiple items of different data types.','Junior','2026-07-03 16:17:55',NULL,NULL),(108,8,'What is the difference between a list and a tuple?','Lists are mutable, while tuples are immutable after creation.','Junior','2026-07-03 16:17:55',NULL,NULL),(109,8,'What is a function in Python?','A function is a reusable block of code that performs a specific task and may accept parameters and return values.','Junior','2026-07-03 16:17:55',NULL,NULL),(110,8,'What are Python dictionaries?','Dictionaries are collections of key-value pairs that provide fast data lookup by key.','Junior','2026-07-03 16:17:55',NULL,NULL),(111,8,'What is a Python virtual environment?','A virtual environment is an isolated Python environment that allows projects to manage dependencies independently.','Mid','2026-07-03 16:17:55',NULL,NULL),(112,8,'What is the difference between deep copy and shallow copy?','A shallow copy copies references to nested objects, while a deep copy recursively copies all nested objects.','Mid','2026-07-03 16:17:55',NULL,NULL),(113,8,'What are list comprehensions?','List comprehensions provide a concise way to create lists by applying expressions and filters to iterable objects.','Mid','2026-07-03 16:17:55',NULL,NULL),(114,8,'What are decorators in Python?','Decorators are functions that modify or extend the behavior of other functions or methods without changing their code.','Mid','2026-07-03 16:17:55',NULL,NULL),(115,8,'What is exception handling in Python?','Exception handling allows programs to manage runtime errors using try, except, else, and finally blocks.','Mid','2026-07-03 16:17:55',NULL,NULL),(116,8,'What is the Global Interpreter Lock (GIL)?','The GIL is a mechanism in CPython that allows only one thread to execute Python bytecode at a time.','Senior','2026-07-03 16:17:55',NULL,NULL),(117,8,'What is the difference between multiprocessing and multithreading in Python?','Multiprocessing uses multiple processes with separate memory spaces, while multithreading uses multiple threads within the same process.','Senior','2026-07-03 16:17:55',NULL,NULL),(118,8,'What are generators and why are they useful?','Generators produce values lazily using the yield keyword, reducing memory consumption for large datasets.','Senior','2026-07-03 16:17:55',NULL,NULL),(119,8,'How does Python memory management work?','Python manages memory through reference counting and a garbage collector that removes cyclic references.','Senior','2026-07-03 16:17:55',NULL,NULL),(120,8,'How would you optimize the performance of a Python application?','Performance can be improved by choosing efficient algorithms and data structures, reducing unnecessary operations, using profiling tools, and leveraging concurrency or caching when appropriate.','Senior','2026-07-03 16:17:55',NULL,NULL),(121,9,'What is Rust?','Rust is a systems programming language focused on performance, memory safety, and concurrency.','Junior','2026-07-03 16:18:22',NULL,NULL),(122,9,'What problem does Rust ownership solve?','Ownership ensures memory safety without requiring a garbage collector by enforcing rules at compile time.','Junior','2026-07-03 16:18:22',NULL,NULL),(123,9,'What is a variable in Rust and how is mutability declared?','Variables are immutable by default and can be made mutable using the mut keyword.','Junior','2026-07-03 16:18:22',NULL,NULL),(124,9,'What is the difference between String and &str?','String is an owned, growable string type, while &str is a borrowed string slice.','Junior','2026-07-03 16:18:22',NULL,NULL),(125,9,'What is a struct in Rust?','A struct is a custom data type that groups related data fields together.','Junior','2026-07-03 16:18:22',NULL,NULL),(126,9,'What are borrowing and references in Rust?','Borrowing allows access to data through references without taking ownership of the value.','Mid','2026-07-03 16:18:22',NULL,NULL),(127,9,'What is the difference between immutable and mutable references?','Immutable references allow read-only access, while mutable references allow modifying the referenced data.','Mid','2026-07-03 16:18:22',NULL,NULL),(128,9,'What is pattern matching in Rust?','Pattern matching uses the match expression to compare values against patterns and execute corresponding code.','Mid','2026-07-03 16:18:22',NULL,NULL),(129,9,'What is the Option type?','Option is an enum used to represent either a value Some(T) or the absence of a value None.','Mid','2026-07-03 16:18:22',NULL,NULL),(130,9,'What is the Result type?','Result is an enum used for error handling and represents either success with Ok(T) or failure with Err(E).','Mid','2026-07-03 16:18:22',NULL,NULL),(131,9,'How does Rust achieve memory safety without a garbage collector?','Rust uses ownership, borrowing, and lifetime rules enforced at compile time to prevent memory-related errors.','Senior','2026-07-03 16:18:22',NULL,NULL),(132,9,'What are lifetimes in Rust?','Lifetimes specify how long references are valid and help the compiler prevent dangling references.','Senior','2026-07-03 16:18:22',NULL,NULL),(133,9,'What is the difference between concurrency and parallelism in Rust?','Concurrency manages multiple tasks at once, while parallelism executes tasks simultaneously on multiple processors or cores.','Senior','2026-07-03 16:18:22',NULL,NULL),(134,9,'What are traits in Rust?','Traits define shared behavior that types can implement, similar to interfaces in other languages.','Senior','2026-07-03 16:18:22',NULL,NULL),(135,9,'How would you optimize the performance of a Rust application?','Performance can be improved by minimizing allocations, using appropriate data structures, leveraging zero-cost abstractions, and profiling bottlenecks.','Senior','2026-07-03 16:18:22',NULL,NULL),(136,10,'What is Go (Golang)?','Go is an open-source programming language developed by Google that focuses on simplicity, performance, and concurrency.','Junior','2026-07-03 16:18:49',NULL,NULL),(137,10,'What is a package in Go?','A package is a collection of Go source files that provide related functionality and can be imported into other programs.','Junior','2026-07-03 16:18:49',NULL,NULL),(138,10,'What is the purpose of the main package?','The main package serves as the entry point of an executable Go application.','Junior','2026-07-03 16:18:49',NULL,NULL),(139,10,'What is the difference between an array and a slice in Go?','Arrays have a fixed size, while slices are dynamic views over arrays and can grow as needed.','Junior','2026-07-03 16:18:49',NULL,NULL),(140,10,'What are pointers in Go?','Pointers store the memory address of a variable and allow direct access to the referenced value.','Junior','2026-07-03 16:18:49',NULL,NULL),(141,10,'What is a goroutine?','A goroutine is a lightweight thread managed by the Go runtime that enables concurrent execution.','Mid','2026-07-03 16:18:49',NULL,NULL),(142,10,'What are channels in Go?','Channels are communication mechanisms that allow goroutines to safely exchange data.','Mid','2026-07-03 16:18:49',NULL,NULL),(143,10,'What is the difference between buffered and unbuffered channels?','Unbuffered channels require both sender and receiver to be ready, while buffered channels can store a limited number of values before blocking.','Mid','2026-07-03 16:18:49',NULL,NULL),(144,10,'What is an interface in Go?','An interface defines a set of method signatures that a type must implement to satisfy the interface.','Mid','2026-07-03 16:18:49',NULL,NULL),(145,10,'How is error handling performed in Go?','Go typically handles errors by returning an error value that callers must explicitly check and handle.','Mid','2026-07-03 16:18:49',NULL,NULL),(146,10,'How does Go manage memory?','Go uses automatic garbage collection to manage memory and reclaim unused objects.','Senior','2026-07-03 16:18:49',NULL,NULL),(147,10,'What are race conditions and how can they be avoided in Go?','Race conditions occur when multiple goroutines access shared data concurrently without synchronization. They can be avoided using channels, mutexes, or other synchronization primitives.','Senior','2026-07-03 16:18:49',NULL,NULL),(148,10,'What is the difference between concurrency and parallelism in Go?','Concurrency is the ability to manage multiple tasks at once, while parallelism executes multiple tasks simultaneously across CPU cores.','Senior','2026-07-03 16:18:49',NULL,NULL),(149,10,'What are contexts in Go and why are they important?','Contexts carry deadlines, cancellation signals, and request-scoped values across API boundaries and goroutines.','Senior','2026-07-03 16:18:49',NULL,NULL),(150,10,'How would you optimize the performance of a Go application?','Performance can be improved by minimizing allocations, using efficient data structures, reducing contention between goroutines, profiling bottlenecks, and leveraging concurrency appropriately.','Senior','2026-07-03 16:18:49',NULL,NULL),(151,11,'What is React?','React is a JavaScript library for building user interfaces using reusable components.','Junior','2026-07-03 16:19:24',NULL,NULL),(152,11,'What is a React component?','A React component is a reusable piece of UI that encapsulates structure, logic, and behavior.','Junior','2026-07-03 16:19:24',NULL,NULL),(153,11,'What is JSX?','JSX is a syntax extension that allows developers to write HTML-like code within JavaScript.','Junior','2026-07-03 16:19:24',NULL,NULL),(154,11,'What are props in React?','Props are read-only inputs passed from a parent component to a child component.','Junior','2026-07-03 16:19:24',NULL,NULL),(155,11,'What is state in React?','State is data managed within a component that can change over time and trigger re-renders.','Junior','2026-07-03 16:19:24',NULL,NULL),(156,11,'What is the difference between props and state?','Props are passed from parent components and cannot be modified by the receiving component, while state is managed internally and can be updated.','Mid','2026-07-03 16:19:24',NULL,NULL),(157,11,'What is the useEffect hook?','The useEffect hook allows components to perform side effects such as data fetching, subscriptions, or DOM updates.','Mid','2026-07-03 16:19:24',NULL,NULL),(158,11,'What is the useState hook?','The useState hook allows functional components to manage and update local state.','Mid','2026-07-03 16:19:24',NULL,NULL),(159,11,'What is conditional rendering in React?','Conditional rendering displays different UI elements based on component state or props.','Mid','2026-07-03 16:19:24',NULL,NULL),(160,11,'Why is the key prop important when rendering lists?','The key prop helps React identify which items have changed, been added, or been removed, improving rendering efficiency.','Mid','2026-07-03 16:19:24',NULL,NULL),(161,11,'What is the Virtual DOM?','The Virtual DOM is an in-memory representation of the UI that React uses to efficiently update the real DOM.','Senior','2026-07-03 16:19:24',NULL,NULL),(162,11,'What is React.memo and when would you use it?','React.memo prevents unnecessary re-renders of functional components by memoizing their rendered output when props do not change.','Senior','2026-07-03 16:19:24',NULL,NULL),(163,11,'What is the difference between useMemo and useCallback?','useMemo memoizes computed values, while useCallback memoizes function references.','Senior','2026-07-03 16:19:24',NULL,NULL),(164,11,'How would you manage state in a large React application?','State can be managed using Context API, Redux, Zustand, Recoil, or other state management solutions depending on application complexity.','Senior','2026-07-03 16:19:24',NULL,NULL),(165,11,'How would you optimize the performance of a React application?','Performance can be improved using memoization, code splitting, lazy loading, avoiding unnecessary re-renders, and optimizing state management.','Senior','2026-07-03 16:19:24',NULL,NULL),(166,12,'What is Node.js?','Node.js is a JavaScript runtime built on the V8 engine that allows JavaScript to run outside the browser.','Junior','2026-07-03 16:20:01',NULL,NULL),(167,12,'What is npm?','npm is the default package manager for Node.js used to install and manage project dependencies.','Junior','2026-07-03 16:20:01',NULL,NULL),(168,12,'What is package.json?','package.json is a configuration file that contains project metadata, scripts, and dependency definitions.','Junior','2026-07-03 16:20:01',NULL,NULL),(169,12,'What is the difference between CommonJS and ES Modules?','CommonJS uses require and module.exports, while ES Modules use import and export statements.','Junior','2026-07-03 16:20:01',NULL,NULL),(170,12,'What is an event-driven architecture?','An event-driven architecture responds to events and actions asynchronously rather than following a strictly sequential flow.','Junior','2026-07-03 16:20:01',NULL,NULL),(171,12,'What is the Node.js event loop?','The event loop is the mechanism that enables Node.js to perform non-blocking I/O operations by handling callbacks and asynchronous tasks.','Mid','2026-07-03 16:20:01',NULL,NULL),(172,12,'What are streams in Node.js?','Streams are objects that allow data to be processed piece by piece instead of loading everything into memory at once.','Mid','2026-07-03 16:20:01',NULL,NULL),(173,12,'What is middleware in Express.js?','Middleware functions execute during the request-response cycle and can modify requests, responses, or pass control to the next handler.','Mid','2026-07-03 16:20:01',NULL,NULL),(174,12,'What is asynchronous programming in Node.js?','Asynchronous programming allows tasks such as file operations and network requests to execute without blocking the main thread.','Mid','2026-07-03 16:20:01',NULL,NULL),(175,12,'What is the difference between process.nextTick() and setImmediate()?','process.nextTick() executes before the next event loop phase, while setImmediate() executes during the check phase of the event loop.','Mid','2026-07-03 16:20:01',NULL,NULL),(176,12,'How does Node.js achieve scalability?','Node.js achieves scalability through its non-blocking I/O model, event loop, clustering, and efficient handling of concurrent connections.','Senior','2026-07-03 16:20:01',NULL,NULL),(177,12,'What is clustering in Node.js?','Clustering allows multiple Node.js processes to share the same server port and utilize multiple CPU cores.','Senior','2026-07-03 16:20:01',NULL,NULL),(178,12,'How would you handle memory leaks in a Node.js application?','Memory leaks can be addressed by removing unnecessary references, cleaning up event listeners, managing caches properly, and profiling memory usage.','Senior','2026-07-03 16:20:01',NULL,NULL),(179,12,'What are worker threads and when would you use them?','Worker threads enable CPU-intensive tasks to run in parallel without blocking the main event loop.','Senior','2026-07-03 16:20:01',NULL,NULL),(180,12,'How would you optimize the performance of a Node.js application?','Performance can be improved through caching, connection pooling, efficient database queries, load balancing, clustering, and minimizing blocking operations.','Senior','2026-07-03 16:20:01',NULL,NULL),(181,13,'What is TypeScript?','TypeScript is a strongly typed superset of JavaScript that compiles into JavaScript.','Junior','2026-07-03 16:22:50',NULL,NULL),(182,13,'Why would you use TypeScript instead of JavaScript?','TypeScript provides static typing, better tooling, and improved maintainability for larger applications.','Junior','2026-07-03 16:22:50',NULL,NULL),(183,13,'What is a type in TypeScript?','A type defines the shape and kind of values that can be assigned to a variable.','Junior','2026-07-03 16:22:50',NULL,NULL),(184,13,'What is the difference between let, const, and var in TypeScript?','Let and const are block-scoped, while var is function-scoped. Const cannot be reassigned after initialization.','Junior','2026-07-03 16:22:50',NULL,NULL),(185,13,'What are interfaces in TypeScript?','Interfaces define contracts that describe the structure of objects.','Junior','2026-07-03 16:22:50',NULL,NULL),(186,13,'What is the difference between an interface and a type alias?','Both define types, but interfaces are extendable and primarily used for object shapes, while type aliases can represent unions, primitives, and complex types.','Mid','2026-07-03 16:22:50',NULL,NULL),(187,13,'What are union types?','Union types allow a variable to hold values of multiple specified types.','Mid','2026-07-03 16:22:50',NULL,NULL),(188,13,'What are generics in TypeScript?','Generics enable reusable components and functions that can work with different data types while maintaining type safety.','Mid','2026-07-03 16:22:50',NULL,NULL),(189,13,'What is type inference?','Type inference allows TypeScript to automatically determine a variable type based on its assigned value.','Mid','2026-07-03 16:22:50',NULL,NULL),(190,13,'What are enums in TypeScript?','Enums are a way to define a set of named constant values.','Mid','2026-07-03 16:22:50',NULL,NULL),(191,13,'What are decorators in TypeScript?','Decorators are special declarations that can modify classes, methods, properties, or parameters, often used in frameworks such as Angular.','Senior','2026-07-03 16:22:50',NULL,NULL),(192,13,'What is the difference between any, unknown, and never?','Any disables type checking, unknown requires type validation before use, and never represents values that never occur.','Senior','2026-07-03 16:22:50',NULL,NULL),(193,13,'What are conditional types?','Conditional types create types based on conditions using a syntax similar to ternary expressions.','Senior','2026-07-03 16:22:50',NULL,NULL),(194,13,'What are mapped types?','Mapped types allow creating new types by transforming properties of existing types.','Senior','2026-07-03 16:22:50',NULL,NULL),(195,13,'How would you improve maintainability in a large TypeScript codebase?','Maintainability can be improved through strict typing, clear interfaces, reusable generics, modular architecture, linting, and comprehensive testing.','Senior','2026-07-03 16:22:50',NULL,NULL),(196,14,'What is Docker?','Docker is a platform that enables applications to be packaged and run in isolated containers.','Junior','2026-07-03 16:23:15',NULL,NULL),(197,14,'What is a Docker container?','A container is a lightweight, isolated runtime environment that includes an application and its dependencies.','Junior','2026-07-03 16:23:15',NULL,NULL),(198,14,'What is a Docker image?','A Docker image is a read-only template used to create containers.','Junior','2026-07-03 16:23:15',NULL,NULL),(199,14,'What is the purpose of a Dockerfile?','A Dockerfile contains instructions for building a Docker image.','Junior','2026-07-03 16:23:15',NULL,NULL),(200,14,'What is the difference between a Docker image and a container?','An image is a template, while a container is a running instance of that image.','Junior','2026-07-03 16:23:15',NULL,NULL),(201,14,'What is Docker Compose?','Docker Compose is a tool for defining and running multi-container applications using a YAML configuration file.','Mid','2026-07-03 16:23:15',NULL,NULL),(202,14,'What are Docker volumes?','Volumes provide persistent storage for containers and allow data to survive container restarts and removals.','Mid','2026-07-03 16:23:15',NULL,NULL),(203,14,'What is the difference between CMD and ENTRYPOINT in a Dockerfile?','CMD provides default commands and arguments, while ENTRYPOINT defines the main executable that always runs when the container starts.','Mid','2026-07-03 16:23:15',NULL,NULL),(204,14,'What are Docker networks?','Docker networks enable communication between containers and external systems.','Mid','2026-07-03 16:23:15',NULL,NULL),(205,14,'How can environment variables be passed to a Docker container?','Environment variables can be defined using the Dockerfile, docker run command, Compose files, or external configuration sources.','Mid','2026-07-03 16:23:15',NULL,NULL),(206,14,'What is a multi-stage Docker build?','A multi-stage build uses multiple build stages in a Dockerfile to reduce image size and separate build dependencies from runtime artifacts.','Senior','2026-07-03 16:23:15',NULL,NULL),(207,14,'How would you optimize the size of a Docker image?','Image size can be reduced by using smaller base images, multi-stage builds, removing unnecessary files, and minimizing layers.','Senior','2026-07-03 16:23:15',NULL,NULL),(208,14,'What are common Docker security best practices?','Best practices include using non-root users, scanning images for vulnerabilities, minimizing image contents, and keeping dependencies updated.','Senior','2026-07-03 16:23:15',NULL,NULL),(209,14,'How does Docker differ from a virtual machine?','Docker containers share the host operating system kernel, while virtual machines include a full guest operating system and hypervisor layer.','Senior','2026-07-03 16:23:15',NULL,NULL),(210,14,'How would you troubleshoot a container that repeatedly crashes?','Review logs, inspect container configuration, verify resource limits, check dependencies, and analyze startup errors to determine the root cause.','Senior','2026-07-03 16:23:15',NULL,NULL),(211,15,'What is Microsoft Azure?','Microsoft Azure is a cloud computing platform that provides services for computing, storage, networking, databases, and application hosting.','Junior','2026-07-03 16:23:36',NULL,NULL),(212,15,'What is an Azure Resource Group?','A Resource Group is a logical container used to organize and manage related Azure resources.','Junior','2026-07-03 16:23:36',NULL,NULL),(213,15,'What is an Azure Virtual Machine?','An Azure Virtual Machine is a scalable cloud-hosted server that runs Windows or Linux operating systems.','Junior','2026-07-03 16:23:36',NULL,NULL),(214,15,'What is Azure App Service?','Azure App Service is a managed platform for hosting web applications, APIs, and backend services.','Junior','2026-07-03 16:23:36',NULL,NULL),(215,15,'What is Azure Blob Storage?','Azure Blob Storage is a service for storing large amounts of unstructured data such as documents, images, and videos.','Junior','2026-07-03 16:23:36',NULL,NULL),(216,15,'What is Azure Functions?','Azure Functions is a serverless compute service that executes code in response to events without requiring infrastructure management.','Mid','2026-07-03 16:23:36',NULL,NULL),(217,15,'What is Azure SQL Database?','Azure SQL Database is a fully managed relational database service based on Microsoft SQL Server.','Mid','2026-07-03 16:23:36',NULL,NULL),(218,15,'What is Azure Key Vault?','Azure Key Vault is a service used to securely store and manage secrets, certificates, and encryption keys.','Mid','2026-07-03 16:23:36',NULL,NULL),(219,15,'What is the difference between Azure App Service and Azure Virtual Machines?','App Service is a managed platform for hosting applications, while Virtual Machines provide full control over the operating system and environment.','Mid','2026-07-03 16:23:36',NULL,NULL),(220,15,'What is Azure Active Directory (Azure AD)?','Azure Active Directory is a cloud-based identity and access management service used for authentication and authorization.','Mid','2026-07-03 16:23:36',NULL,NULL),(221,15,'How would you design a highly available application in Azure?','A highly available application can be designed using multiple availability zones, load balancing, redundancy, and automated failover mechanisms.','Senior','2026-07-03 16:23:36',NULL,NULL),(222,15,'What are Azure Availability Zones and Availability Sets?','Availability Zones provide physically separate datacenter locations, while Availability Sets distribute virtual machines across fault and update domains within a datacenter.','Senior','2026-07-03 16:23:36',NULL,NULL),(223,15,'How can Azure Monitor be used to improve application reliability?','Azure Monitor collects metrics, logs, and telemetry to detect issues, generate alerts, and support troubleshooting and performance analysis.','Senior','2026-07-03 16:23:36',NULL,NULL),(224,15,'What is Infrastructure as Code in Azure?','Infrastructure as Code is the practice of provisioning and managing Azure resources using templates and automation tools such as ARM, Bicep, or Terraform.','Senior','2026-07-03 16:23:36',NULL,NULL),(225,15,'How would you optimize costs in an Azure environment?','Costs can be optimized through right-sizing resources, auto-scaling, reserved instances, monitoring usage, and removing unused resources.','Senior','2026-07-03 16:23:36',NULL,NULL),(226,16,'What is Kubernetes?','Kubernetes is an open-source container orchestration platform used to deploy, manage, and scale containerized applications.','Junior','2026-07-03 16:24:12',NULL,NULL),(227,16,'What is a Pod in Kubernetes?','A Pod is the smallest deployable unit in Kubernetes and can contain one or more containers.','Junior','2026-07-03 16:24:12',NULL,NULL),(228,16,'What is a Node in Kubernetes?','A Node is a worker machine, either physical or virtual, that runs Pods.','Junior','2026-07-03 16:24:12',NULL,NULL),(229,16,'What is a Deployment?','A Deployment manages the creation, update, and scaling of Pods in a Kubernetes cluster.','Junior','2026-07-03 16:24:12',NULL,NULL),(230,16,'What is kubectl?','kubectl is the command-line tool used to interact with and manage Kubernetes clusters.','Junior','2026-07-03 16:24:12',NULL,NULL),(231,16,'What is the difference between a Deployment and a StatefulSet?','Deployments are used for stateless applications, while StatefulSets are designed for applications requiring stable identities and persistent storage.','Mid','2026-07-03 16:24:12',NULL,NULL),(232,16,'What is a Service in Kubernetes?','A Service provides a stable network endpoint to access a set of Pods.','Mid','2026-07-03 16:24:12',NULL,NULL),(233,16,'What is a ConfigMap?','A ConfigMap stores non-sensitive configuration data that can be consumed by applications running in Kubernetes.','Mid','2026-07-03 16:24:12',NULL,NULL),(234,16,'What is a Secret in Kubernetes?','A Secret stores sensitive information such as passwords, tokens, and certificates securely.','Mid','2026-07-03 16:24:12',NULL,NULL),(235,16,'What is Horizontal Pod Autoscaling?','Horizontal Pod Autoscaling automatically adjusts the number of Pods based on resource utilization or custom metrics.','Mid','2026-07-03 16:24:12',NULL,NULL),(236,16,'What is an Ingress and when would you use it?','An Ingress manages external HTTP and HTTPS access to services in a Kubernetes cluster and provides routing capabilities.','Senior','2026-07-03 16:24:12',NULL,NULL),(237,16,'How does Kubernetes perform rolling updates?','Kubernetes gradually replaces old Pods with new ones while ensuring application availability during deployments.','Senior','2026-07-03 16:24:12',NULL,NULL),(238,16,'How would you secure a Kubernetes cluster?','Security can be improved using RBAC, network policies, secrets management, image scanning, and restricting container privileges.','Senior','2026-07-03 16:24:12',NULL,NULL),(239,16,'What is the purpose of etcd in Kubernetes?','etcd is a distributed key-value store used by Kubernetes to persist cluster configuration and state.','Senior','2026-07-03 16:24:12',NULL,NULL),(240,16,'How would you troubleshoot a Pod that is not starting?','Check Pod events, container logs, resource limits, image availability, configuration issues, and node status to identify the root cause.','Senior','2026-07-03 16:24:12',NULL,NULL),(241,17,'What is AWS?','AWS is a cloud computing platform provided by Amazon that offers services for computing, storage, networking, databases, and more.','Junior','2026-07-03 16:24:44',NULL,NULL),(242,17,'What is Amazon EC2?','Amazon EC2 is a service that provides scalable virtual servers in the cloud.','Junior','2026-07-03 16:24:44',NULL,NULL),(243,17,'What is Amazon S3?','Amazon S3 is an object storage service used to store and retrieve data with high durability and scalability.','Junior','2026-07-03 16:24:44',NULL,NULL),(244,17,'What is an AWS Region?','An AWS Region is a geographical area that contains multiple isolated data centers where AWS resources can be deployed.','Junior','2026-07-03 16:24:44',NULL,NULL),(245,17,'What is IAM in AWS?','IAM, or Identity and Access Management, is a service used to securely manage access to AWS resources.','Junior','2026-07-03 16:24:44',NULL,NULL),(246,17,'What is the difference between EC2 and Lambda?','EC2 provides virtual servers that require management, while Lambda is a serverless service that executes code in response to events.','Mid','2026-07-03 16:24:44',NULL,NULL),(247,17,'What is an AWS VPC?','A Virtual Private Cloud is a logically isolated network where AWS resources can be launched and managed securely.','Mid','2026-07-03 16:24:44',NULL,NULL),(248,17,'What is Amazon RDS?','Amazon RDS is a managed relational database service that simplifies database setup, operation, and scaling.','Mid','2026-07-03 16:24:44',NULL,NULL),(249,17,'What are Security Groups in AWS?','Security Groups act as virtual firewalls that control inbound and outbound traffic for AWS resources.','Mid','2026-07-03 16:24:44',NULL,NULL),(250,17,'What is the purpose of CloudWatch?','Amazon CloudWatch provides monitoring, logging, metrics, and alerting for AWS resources and applications.','Mid','2026-07-03 16:24:44',NULL,NULL),(251,17,'How would you design a highly available application in AWS?','A highly available application can be designed using multiple Availability Zones, load balancers, auto scaling, and redundant storage.','Senior','2026-07-03 16:24:44',NULL,NULL),(252,17,'What is Auto Scaling and why is it important?','Auto Scaling automatically adjusts resource capacity based on demand to improve availability and optimize costs.','Senior','2026-07-03 16:24:44',NULL,NULL),(253,17,'How would you secure an AWS environment?','Security can be improved through least-privilege IAM policies, network segmentation, encryption, monitoring, and regular security audits.','Senior','2026-07-03 16:24:44',NULL,NULL),(254,17,'What is Infrastructure as Code in AWS?','Infrastructure as Code is the practice of provisioning and managing AWS resources using tools such as CloudFormation or Terraform.','Senior','2026-07-03 16:24:44',NULL,NULL),(255,17,'How would you optimize costs in AWS?','Costs can be optimized through right-sizing resources, Reserved Instances, Savings Plans, auto scaling, monitoring usage, and removing unused resources.','Senior','2026-07-03 16:24:44',NULL,NULL),(256,18,'What is MongoDB?','MongoDB is a NoSQL document-oriented database that stores data in flexible JSON-like documents.','Junior','2026-07-03 16:25:27',NULL,NULL),(257,18,'What is a document in MongoDB?','A document is the basic unit of data in MongoDB and is stored in BSON format.','Junior','2026-07-03 16:25:27',NULL,NULL),(258,18,'What is a collection in MongoDB?','A collection is a group of related documents, similar to a table in a relational database.','Junior','2026-07-03 16:25:27',NULL,NULL),(259,18,'What is BSON?','BSON is a binary representation of JSON used internally by MongoDB to store documents efficiently.','Junior','2026-07-03 16:25:27',NULL,NULL),(260,18,'How does MongoDB differ from a relational database?','MongoDB stores data as flexible documents rather than rows and tables with a fixed schema.','Junior','2026-07-03 16:25:27',NULL,NULL),(261,18,'What is an index in MongoDB?','An index improves query performance by allowing MongoDB to locate documents more efficiently.','Mid','2026-07-03 16:25:27',NULL,NULL),(262,18,'What is the _id field in MongoDB?','The _id field is a unique identifier automatically assigned to each document in a collection.','Mid','2026-07-03 16:25:27',NULL,NULL),(263,18,'What is aggregation in MongoDB?','Aggregation is a framework used to process, transform, and analyze data through a pipeline of stages.','Mid','2026-07-03 16:25:27',NULL,NULL),(264,18,'What is the difference between embedded documents and references?','Embedded documents store related data within a document, while references link documents across collections.','Mid','2026-07-03 16:25:27',NULL,NULL),(265,18,'What is replication in MongoDB?','Replication creates copies of data across multiple servers to improve availability and fault tolerance.','Mid','2026-07-03 16:25:27',NULL,NULL),(266,18,'What is sharding in MongoDB?','Sharding distributes data across multiple servers to support horizontal scaling and large datasets.','Senior','2026-07-03 16:25:27',NULL,NULL),(267,18,'How would you choose between embedding and referencing data?','Embedding is suitable for frequently accessed related data, while referencing is better for large or independently managed data relationships.','Senior','2026-07-03 16:25:27',NULL,NULL),(268,18,'What are replica sets?','A replica set is a group of MongoDB servers that maintain the same data set and provide automatic failover.','Senior','2026-07-03 16:25:27',NULL,NULL),(269,18,'How would you optimize MongoDB query performance?','Performance can be optimized using appropriate indexes, efficient queries, aggregation tuning, and proper schema design.','Senior','2026-07-03 16:25:27',NULL,NULL),(270,18,'How would you design a scalable MongoDB architecture?','A scalable architecture typically uses sharding, replica sets, monitoring, indexing strategies, and proper data modeling practices.','Senior','2026-07-03 16:25:27',NULL,NULL),(271,19,'What is MySQL?','MySQL is an open-source relational database management system that stores and manages data using SQL.','Junior','2026-07-03 16:26:04',NULL,NULL),(272,19,'What is a primary key?','A primary key uniquely identifies each row in a table and cannot contain NULL values.','Junior','2026-07-03 16:26:04',NULL,NULL),(273,19,'What is the difference between a table and a database?','A database is a collection of related tables, while a table stores data in rows and columns.','Junior','2026-07-03 16:26:04',NULL,NULL),(274,19,'What is SQL?','SQL is a language used to create, query, update, and manage relational databases.','Junior','2026-07-03 16:26:04',NULL,NULL),(275,19,'What is a foreign key?','A foreign key is a column that establishes a relationship between two tables by referencing a primary key in another table.','Junior','2026-07-03 16:26:04',NULL,NULL),(276,19,'What is the difference between INNER JOIN and LEFT JOIN?','INNER JOIN returns matching records from both tables, while LEFT JOIN returns all records from the left table and matching records from the right table.','Mid','2026-07-03 16:26:04',NULL,NULL),(277,19,'What is an index and why is it important?','An index improves query performance by allowing the database to find rows more efficiently.','Mid','2026-07-03 16:26:04',NULL,NULL),(278,19,'What is normalization?','Normalization is the process of organizing data to reduce redundancy and improve data integrity.','Mid','2026-07-03 16:26:04',NULL,NULL),(279,19,'What is a transaction in MySQL?','A transaction is a sequence of operations executed as a single unit of work that can be committed or rolled back.','Mid','2026-07-03 16:26:04',NULL,NULL),(280,19,'What are the ACID properties?','ACID stands for Atomicity, Consistency, Isolation, and Durability, which ensure reliable transaction processing.','Mid','2026-07-03 16:26:04',NULL,NULL),(281,19,'What is the difference between InnoDB and MyISAM?','InnoDB supports transactions, row-level locking, and foreign keys, while MyISAM is optimized for read-heavy workloads and does not support transactions.','Senior','2026-07-03 16:26:04',NULL,NULL),(282,19,'How would you optimize a slow MySQL query?','Query performance can be improved by using indexes, analyzing execution plans, reducing unnecessary data retrieval, and optimizing joins.','Senior','2026-07-03 16:26:04',NULL,NULL),(283,19,'What is database replication in MySQL?','Replication copies data from one MySQL server to one or more replica servers to improve availability and scalability.','Senior','2026-07-03 16:26:04',NULL,NULL),(284,19,'What is the purpose of EXPLAIN in MySQL?','The EXPLAIN statement provides information about how MySQL executes a query and helps identify performance issues.','Senior','2026-07-03 16:26:04',NULL,NULL),(285,19,'How would you design a scalable MySQL architecture?','A scalable architecture can use replication, partitioning, caching, connection pooling, query optimization, and proper indexing strategies.','Senior','2026-07-03 16:26:04',NULL,NULL),(286,20,'What is SQL Server?','SQL Server is a relational database management system developed by Microsoft for storing, managing, and querying data.','Junior','2026-07-03 16:26:40',NULL,NULL),(287,20,'What is a primary key?','A primary key uniquely identifies each row in a table and cannot contain NULL values.','Junior','2026-07-03 16:26:40',NULL,NULL),(288,20,'What is a foreign key?','A foreign key establishes a relationship between tables by referencing a primary key in another table.','Junior','2026-07-03 16:26:40',NULL,NULL),(289,20,'What is a stored procedure?','A stored procedure is a precompiled collection of SQL statements that can be executed as a single unit.','Junior','2026-07-03 16:26:40',NULL,NULL),(290,20,'What is the difference between DELETE and TRUNCATE?','DELETE removes rows individually and can be rolled back, while TRUNCATE removes all rows more efficiently by deallocating data pages.','Junior','2026-07-03 16:26:40',NULL,NULL),(291,20,'What is a clustered index?','A clustered index determines the physical order of data in a table and a table can have only one clustered index.','Mid','2026-07-03 16:26:40',NULL,NULL),(292,20,'What is a non-clustered index?','A non-clustered index is a separate structure that improves query performance by storing indexed values and pointers to table rows.','Mid','2026-07-03 16:26:40',NULL,NULL),(293,20,'What is a view in SQL Server?','A view is a virtual table based on the result of a SQL query.','Mid','2026-07-03 16:26:40',NULL,NULL),(294,20,'What is a transaction?','A transaction is a sequence of operations that are treated as a single unit of work and can be committed or rolled back.','Mid','2026-07-03 16:26:40',NULL,NULL),(295,20,'What are the ACID properties?','ACID stands for Atomicity, Consistency, Isolation, and Durability, ensuring reliable transaction processing.','Mid','2026-07-03 16:26:40',NULL,NULL),(296,20,'What is the difference between a clustered and non-clustered index?','A clustered index stores data rows in index order, while a non-clustered index stores pointers to the actual data rows.','Senior','2026-07-03 16:26:40',NULL,NULL),(297,20,'How would you identify and troubleshoot slow SQL Server queries?','Use execution plans, Query Store, SQL Profiler, DMVs, and indexing analysis to identify bottlenecks and optimize query performance.','Senior','2026-07-03 16:26:40',NULL,NULL),(298,20,'What is SQL Server Always On Availability Groups?','Always On Availability Groups provide high availability and disaster recovery by replicating databases across multiple SQL Server instances.','Senior','2026-07-03 16:26:40',NULL,NULL),(299,20,'What is parameter sniffing?','Parameter sniffing occurs when SQL Server generates and caches an execution plan based on specific parameter values that may not be optimal for future executions.','Senior','2026-07-03 16:26:40',NULL,NULL),(300,20,'How would you optimize a large SQL Server database?','Optimization techniques include proper indexing, partitioning, query tuning, maintenance plans, statistics management, and monitoring resource utilization.','Senior','2026-07-03 16:26:40',NULL,NULL),(301,21,'What is PostgreSQL?','PostgreSQL is an open-source relational database management system known for reliability, extensibility, and standards compliance.','Junior','2026-07-03 16:27:07',NULL,NULL),(302,21,'What is a primary key?','A primary key uniquely identifies each row in a table and cannot contain NULL values.','Junior','2026-07-03 16:27:07',NULL,NULL),(303,21,'What is a foreign key?','A foreign key creates a relationship between tables by referencing a primary key in another table.','Junior','2026-07-03 16:27:07',NULL,NULL),(304,21,'What is the difference between PostgreSQL and MySQL?','PostgreSQL offers advanced SQL features, extensibility, and strong standards compliance, while MySQL is often chosen for simplicity and ease of use.','Junior','2026-07-03 16:27:07',NULL,NULL),(305,21,'What is a sequence in PostgreSQL?','A sequence is a database object used to generate unique numeric values, commonly for primary keys.','Junior','2026-07-03 16:27:07',NULL,NULL),(306,21,'What is an index and why is it important?','An index improves query performance by allowing PostgreSQL to locate rows more efficiently.','Mid','2026-07-03 16:27:07',NULL,NULL),(307,21,'What is a view in PostgreSQL?','A view is a virtual table based on the result of a query.','Mid','2026-07-03 16:27:07',NULL,NULL),(308,21,'What are transactions in PostgreSQL?','Transactions group multiple operations into a single unit of work that can be committed or rolled back.','Mid','2026-07-03 16:27:07',NULL,NULL),(309,21,'What are the ACID properties?','ACID stands for Atomicity, Consistency, Isolation, and Durability, ensuring reliable transaction processing.','Mid','2026-07-03 16:27:07',NULL,NULL),(310,21,'What is the difference between DELETE, TRUNCATE, and DROP?','DELETE removes rows, TRUNCATE removes all rows more efficiently, and DROP removes the entire database object.','Mid','2026-07-03 16:27:07',NULL,NULL),(311,21,'What is MVCC in PostgreSQL?','MVCC, or Multi-Version Concurrency Control, allows multiple transactions to access data concurrently without excessive locking.','Senior','2026-07-03 16:27:07',NULL,NULL),(312,21,'What is the purpose of VACUUM in PostgreSQL?','VACUUM reclaims storage occupied by dead tuples and helps maintain database performance.','Senior','2026-07-03 16:27:07',NULL,NULL),(313,21,'How would you optimize a slow PostgreSQL query?','Optimization can be achieved through indexing, analyzing execution plans, query rewriting, partitioning, and configuration tuning.','Senior','2026-07-03 16:27:07',NULL,NULL),(314,21,'What is table partitioning in PostgreSQL?','Table partitioning divides large tables into smaller pieces to improve manageability and query performance.','Senior','2026-07-03 16:27:07',NULL,NULL),(315,21,'How would you design a highly available PostgreSQL deployment?','High availability can be achieved using replication, failover mechanisms, backups, monitoring, and redundancy across multiple servers.','Senior','2026-07-03 16:27:07',NULL,NULL);
/*!40000 ALTER TABLE `questions` ENABLE KEYS */;
UNLOCK TABLES;

